contract:
{
  "interface": {
    "mode": "stdin_stdout",
    "signature": "stdin -> stdout",
    "input_channel": "stdin",
    "output_channel": "stdout"
  },
  "preconditions": [
    {
      "id": "P1",
      "expression": "q >= 1 and q <= 10",
      "description": "The number of queries q is between 1 and 10 inclusive."
    },
    {
      "id": "P2",
      "expression": "all(2 <= n <= 1000 for n in [int(lines[i].split()[0]) for i in range(1, len(lines)) if i % 2 == 0 or (i % 2 == 1 and i < len(lines) and not lines[i].strip().isdigit())])",
      "description": "For each query, the number of nodes n is between 2 and 1000 inclusive."
    },
    {
      "id": "P3",
      "expression": "all(1 <= m <= n*(n-1)//2 for n, m in [(int(lines[i].split()[0]), int(lines[i].split()[1])) for i in range(1, len(lines)) if i % 2 == 0])",
      "description": "For each query, the number of edges m is between 1 and n*(n-1)/2 inclusive."
    },
    {
      "id": "P4",
      "expression": "all(1 <= u <= n and 1 <= v <= n for n, m in [(int(lines[i].split()[0]), int(lines[i].split()[1])) for i in range(1, len(lines)) if i % 2 == 0] for u, v in [(int(lines[i+1].split()[0]), int(lines[i+1].split()[1])) for i in range(1, len(lines)) if i % 2 == 0])",
      "description": "For each edge in a query, both endpoints u and v are valid node labels between 1 and n."
    },
    {
      "id": "P5",
      "expression": "all(1 <= s <= n for n, s in [(int(lines[i].split()[0]), int(lines[i+1+m].strip())) for i in range(1, len(lines)) if i % 2 == 0 for m in [int(lines[i].split()[1])]])",
      "description": "For each query, the start node s is a valid node label between 1 and n."
    }
  ],
  "postconditions": [
    {
      "id": "Q1",
      "expression": "len(stdout.strip().split('\\n')) == q",
      "description": "The output contains exactly q lines, one for each query."
    },
    {
      "id": "Q2",
      "expression": "all(len(line.split()) == n - 1 for line in stdout.strip().split('\\n') for n in [int(lines[i].split()[0]) for i in range(1, len(lines)) if i % 2 == 0])",
      "description": "Each output line contains exactly n-1 integers, corresponding to distances to nodes 2 through n."
    },
    {
      "id": "Q3",
      "expression": "all(val == -1 or val % 6 == 0 for line in stdout.strip().split('\\n') for val in [int(x) for x in line.split()])",
      "description": "Each distance value is either -1 (unreachable) or a non-negative multiple of 6."
    },
    {
      "id": "Q4",
      "expression": "all(all((dist == -1) == (node not in reachable_nodes) or (dist == 6 * min_steps) for node, dist in zip(range(1, n+1), [int(x) for x in line.split()]) for line in stdout.strip().split('\\n') for n in [int(lines[i].split()[0]) for i in range(1, len(lines)) if i % 2 == 0] for reachable_nodes, min_steps in [({s}, {s: 0}) for s in [int(lines[i+1+m].strip()) for i in range(1, len(lines)) if i % 2 == 0 for m in [int(lines[i].split()[1])]])])
